def digit_product(n):
    p = 1
    for d in str(abs(n)):
        p *= int(d)
    return p

def reverse_integer(n):
    sign = -1 if n < 0 else 1
    return sign * int(str(abs(n))[::-1])

def is_palindrome_number(n):
    if n < 0:
        return False
    s = str(n)
    return s == s[::-1]

def is_perfect_number(n):
    if n < 1:
        return False
    return sum(d for d in range(1, n) if n % d == 0) == n

def is_abundant_number(n):
    if n < 1:
        return False
    return sum(d for d in range(1, n) if n % d == 0) > n

def is_deficient_number(n):
    if n < 1:
        return False
    return sum(d for d in range(1, n) if n % d == 0) < n

def collatz_length(n):
    count = 1
    while n != 1:
        n = n // 2 if n % 2 == 0 else 3 * n + 1
        count += 1
    return count

def collatz_max_value(n):
    m = n
    while n != 1:
        n = n // 2 if n % 2 == 0 else 3 * n + 1
        m = max(m, n)
    return m

def decimal_to_base(n, base):
    if n == 0:
        return "0"
    digits = "0123456789abcdefghijklmnopqrstuvwxyz"
    neg = n < 0
    n = abs(n)
    out = []
    while n:
        out.append(digits[n % base])
        n //= base
    if neg:
        out.append('-')
    return ''.join(reversed(out))

def gcd_two(a, b):
    a, b = abs(a), abs(b)
    while b:
        a, b = b, a % b
    return a

def lcm_two(a, b):
    if a == 0 or b == 0:
        return 0
    a, b = abs(a), abs(b)
    x, y = a, b
    while y:
        x, y = y, x % y
    return a // x * b

def gcd_list(nums):
    def g(a, b):
        a, b = abs(a), abs(b)
        while b:
            a, b = b, a % b
        return a
    result = 0
    for x in nums:
        result = g(result, x)
    return result

def lcm_list(nums):
    def g(a, b):
        a, b = abs(a), abs(b)
        while b:
            a, b = b, a % b
        return a
    result = 1
    for x in nums:
